css:
.mtb-mesh-drift{position:relative;box-sizing:border-box;width:100%;min-height:190px;padding:18px 18px 17px;border-radius:16px;overflow:hidden;isolation:isolate;background:#0a0c14;color:#f2f4fb;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.mtb-mesh-drift-mesh{position:absolute;inset:-32%;z-index:0;filter:blur(30px) saturate(150%);}
.mtb-mesh-drift-blob{position:absolute;width:60%;height:66%;border-radius:50%;mix-blend-mode:screen;will-change:transform;}
.mtb-mesh-drift-b1{left:0;top:2%;background:radial-gradient(circle at 50% 50%,#4b5bff 0%,rgba(75,91,255,0) 70%);animation:mtb-mesh-drift-a 17s ease-in-out infinite;}
.mtb-mesh-drift-b2{right:-8%;top:-6%;background:radial-gradient(circle at 50% 50%,#b13cff 0%,rgba(177,60,255,0) 70%);animation:mtb-mesh-drift-b 19s ease-in-out infinite;}
.mtb-mesh-drift-b3{left:8%;bottom:-10%;background:radial-gradient(circle at 50% 50%,#12d6c0 0%,rgba(18,214,192,0) 70%);animation:mtb-mesh-drift-c 21s ease-in-out infinite;}
.mtb-mesh-drift-b4{right:2%;bottom:-14%;background:radial-gradient(circle at 50% 50%,#ff5f7e 0%,rgba(255,95,126,0) 70%);animation:mtb-mesh-drift-d 25s ease-in-out infinite;}
.mtb-mesh-drift-veil{position:absolute;inset:0;z-index:1;background:radial-gradient(135% 110% at 24% 4%,rgba(10,12,20,0) 0%,rgba(10,12,20,.42) 52%,rgba(10,12,20,.86) 100%);}
.mtb-mesh-drift-body{position:relative;z-index:2;max-width:31ch;}
.mtb-mesh-drift-eyebrow{margin:0 0 8px;font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#c2c9e4;text-shadow:0 1px 8px rgba(10,12,20,.8);}
.mtb-mesh-drift-title{margin:0 0 6px;font-size:17px;line-height:1.25;letter-spacing:-.012em;font-weight:650;text-shadow:0 2px 14px rgba(10,12,20,.8);}
.mtb-mesh-drift-sub{margin:0 0 14px;font-size:12px;line-height:1.5;color:#c9cfe4;text-shadow:0 1px 8px rgba(10,12,20,.7);}
.mtb-mesh-drift-actions{display:flex;flex-wrap:wrap;gap:8px;}
.mtb-mesh-drift-btn{box-sizing:border-box;padding:8px 14px;border:0;border-radius:999px;background:#f2f4fb;color:#0a0c14;font:inherit;font-size:12px;font-weight:600;cursor:pointer;transition:transform .18s ease,box-shadow .18s ease;}
.mtb-mesh-drift-btn:hover{transform:translateY(-1px);box-shadow:0 10px 22px rgba(0,0,0,.5);}
.mtb-mesh-drift-btn:active{transform:translateY(0) scale(.97);}
.mtb-mesh-drift-btn:focus-visible{outline:2px solid #8fa2ff;outline-offset:3px;}
.mtb-mesh-drift-ghost{box-sizing:border-box;padding:8px 14px;border:1px solid rgba(255,255,255,.22);border-radius:999px;background:rgba(255,255,255,.06);color:#e8ecf9;font:inherit;font-size:12px;font-weight:550;cursor:pointer;transition:background-color .2s ease,border-color .2s ease;}
.mtb-mesh-drift-ghost:hover{background:rgba(255,255,255,.13);}
.mtb-mesh-drift-ghost:active{transform:scale(.97);}
.mtb-mesh-drift-ghost:focus-visible{outline:2px solid #8fa2ff;outline-offset:3px;}
.mtb-mesh-drift-ghost[aria-pressed="true"]{background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.42);}
.mtb-mesh-drift-still .mtb-mesh-drift-blob{animation-play-state:paused;}
@keyframes mtb-mesh-drift-a{0%,100%{transform:translate3d(0,0,0) scale(1);}33%{transform:translate3d(28%,16%,0) scale(1.2);}66%{transform:translate3d(-12%,24%,0) scale(.9);}}
@keyframes mtb-mesh-drift-b{0%,100%{transform:translate3d(0,0,0) scale(1.05);}40%{transform:translate3d(-26%,20%,0) scale(.88);}70%{transform:translate3d(-8%,-14%,0) scale(1.22);}}
@keyframes mtb-mesh-drift-c{0%,100%{transform:translate3d(0,0,0) scale(.95);}45%{transform:translate3d(34%,-22%,0) scale(1.15);}75%{transform:translate3d(12%,10%,0) scale(1.02);}}
@keyframes mtb-mesh-drift-d{0%,100%{transform:translate3d(0,0,0) scale(1.1);}38%{transform:translate3d(-30%,-18%,0) scale(.92);}68%{transform:translate3d(-6%,12%,0) scale(1.18);}}
@media (prefers-reduced-motion: reduce){
.mtb-mesh-drift-blob{animation:none;}
.mtb-mesh-drift-btn{transition:none;}
}

