var ghost = root.querySelector('.mtb-mesh-drift-ghost');
if (!ghost) return;
ghost.addEventListener('click', function () {
  var paused = ghost.getAttribute('aria-pressed') === 'true';
  ghost.setAttribute('aria-pressed', paused ? 'false' : 'true');
  ghost.textContent = paused ? 'Pause motion' : 'Resume motion';
  if (paused) { root.classList.remove('mtb-mesh-drift-still'); }
  else { root.classList.add('mtb-mesh-drift-still'); }
});

