.mtb-particle-drift{position:relative;box-sizing:border-box;width:100%;min-height:186px;padding:16px;border-radius:16px;overflow:hidden;background:radial-gradient(120% 100% at 82% 8%,#102733 0%,#070b12 68%);color:#e6f6fb;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
