}

js:
var cv = root.querySelector('.mtb-particle-drift-canvas');
if (!cv) return;
var ctx = cv.getContext('2d');
var num = root.querySelector('.mtb-particle-drift-num');
var opts = root.querySelectorAll('.mtb-particle-drift-opt');
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var w = 1, h = 1, ps = [], density = 1, px = -999, py = -999;

function build() {
  var n = Math.round(Math.max(24, Math.min(78, (w * h) / 1500 * density)));
  ps = [];
  for (var i = 0; i < n; i++) {
    ps.push({
      x: Math.random() * w, y: Math.random() * h,
      r: 0.7 + Math.random() * 1.5,
      vx: (Math.random() - 0.5) * 0.09,
      vy: -(0.04 + Math.random() * 0.14),
      t: Math.random() * 6.283
    });
  }
  if (num) num.textContent = String(n);
}
function resize() {
  w = Math.max(1, cv.clientWidth);
  h = Math.max(1, cv.clientHeight);
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  build();
}
function draw() {
  ctx.clearRect(0, 0, w, h);
  var i, j, p, q, dx, dy, d2;
  ctx.lineWidth = 1;
  for (i = 0; i < ps.length; i++) {
    p = ps[i];
    for (j = i + 1; j < ps.length; j++) {
      q = ps[j];
      dx = p.x - q.x; dy = p.y - q.y;
      d2 = dx * dx + dy * dy;
      if (d2 < 2200) {
        ctx.strokeStyle = 'rgba(92,214,232,' + (0.16 * (1 - d2 / 2500)).toFixed(3) + ')';
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(q.x, q.y);
        ctx.stroke();
      }
    }
  }
  for (i = 0; i < ps.length; i++) {
    p = ps[i];
    dx = p.x - px; dy = p.y - py;
    var near = Math.max(0, 1 - (dx * dx + dy * dy) / 8000);
    var a = 0.26 + 0.4 * Math.abs(Math.sin(p.t)) + 0.5 * near;
    ctx.fillStyle = 'rgba(158,244,248,' + Math.min(0.95, a).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r + near * 1.5, 0, 6.2832);
    ctx.fill();
  }
}
function step() {
  for (var i = 0; i < ps.length; i++) {
    var p = ps[i];
    p.x += p.vx; p.y += p.vy; p.t += 0.021;
    if (p.y < -6) { p.y = h + 6; p.x = Math.random() * w; }
    if (p.x < -6) { p.x = w + 6; }
    if (p.x > w + 6) { p.x = -6; }
  }
}
function frame() {
  if (!root.isConnected) return;
  step();
  draw();
  window.requestAnimationFrame(frame);
}
root.addEventListener('pointermove', function (e) {
  var r = cv.getBoundingClientRect();
  px = e.clientX - r.left; py = e.clientY - r.top;
});
root.addEventListener('pointerleave', function () { px = -999; py = -999; });
Array.prototype.forEach.call(opts, function (b) {
  b.addEventListener('click', function () {
    Array.prototype.forEach.call(opts, function (o) {
      o.setAttribute('aria-pressed', o === b ? 'true' : 'false');
    });
    density = parseFloat(b.getAttribute('data-d')) || 1;
    build();
    if (reduce) draw();
  });
});
resize();
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { resize(); if (reduce) draw(); });
  ro.observe(cv);
}
if (reduce) { draw(); } else { window.requestAnimationFrame(frame); }

