var cv = root.querySelector('.mtb-grain-veil-canvas');
if (!cv) return;
var ctx = cv.getContext('2d');
var opts = root.querySelectorAll('.mtb-grain-veil-opt');
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var amount = 0.24, w = 1, h = 1, idx = 0, last = 0;
var pats = [];

function buildTiles() {
  pats = [];
  for (var f = 0; f < 4; f++) {
    var tile = document.createElement('canvas');
    tile.width = 96; tile.height = 96;
    var tctx = tile.getContext('2d');
    var img = tctx.createImageData(96, 96);
    var d = img.data;
    for (var i = 0; i < d.length; i += 4) {
      var v = Math.floor(45 + Math.random() * 210);
      d[i] = v; d[i + 1] = v; d[i + 2] = v;
      d[i + 3] = Math.floor(150 + Math.random() * 105);
    }
    tctx.putImageData(img, 0, 0);
    pats.push(ctx.createPattern(tile, 'repeat'));
  }
}
function resize() {
  w = Math.max(1, cv.clientWidth);
  h = Math.max(1, cv.clientHeight);
  cv.width = w; cv.height = h;
}
function draw() {
  if (!pats.length) return;
  ctx.clearRect(0, 0, w, h);
  ctx.globalAlpha = amount;
  ctx.fillStyle = pats[idx];
  ctx.save();
  ctx.translate(-Math.floor(Math.random() * 96), -Math.floor(Math.random() * 96));
  ctx.fillRect(0, 0, w + 96, h + 96);
  ctx.restore();
  ctx.globalAlpha = 1;
}
function frame(t) {
  if (!root.isConnected) return;
  if (t - last > 76) { last = t; idx = (idx + 1) % pats.length; draw(); }
  window.requestAnimationFrame(frame);
}
Array.prototype.forEach.call(opts, function (b) {
  b.addEventListener('click', function () {
    Array.prototype.forEach.call(opts, function (o) {
      o.setAttribute('aria-pressed', o === b ? 'true' : 'false');
    });
    amount = parseFloat(b.getAttribute('data-g')) || 0.24;
    draw();
  });
});
resize();
buildTiles();
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { resize(); draw(); });
  ro.observe(cv);
}
