var ctx = cv.getContext('2d');
var track = root.querySelector('.mtb-starfield-slow-track');
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var w = 1, h = 1, stars = [], t = 0, meteor = null, nextMeteor = 3.5;

function build() {
  stars = [];
  var n = Math.round(Math.max(40, Math.min(130, (w * h) / 620)));
  for (var i = 0; i < n; i++) {
    var depth = 1 + Math.floor(Math.random() * 3);
    stars.push({
      x: Math.random() * w,
      y: Math.random() * h,
      r: depth === 3 ? 1.25 : (depth === 2 ? 0.85 : 0.55),
      v: depth * 0.014,
      a: 0.2 + depth * 0.2,
      p: Math.random() * 6.283,
      s: 0.4 + Math.random() * 0.9
    });
  }
}
function resize() {
  w = Math.max(1, cv.clientWidth);
  h = Math.max(1, cv.clientHeight);
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  build();
}
function draw() {
  ctx.clearRect(0, 0, w, h);
  for (var i = 0; i < stars.length; i++) {
    var st = stars[i];
    var tw = 0.72 + 0.28 * Math.sin(t * st.s + st.p);
