var cv = root.querySelector('.mtb-dust-motes-canvas');
var ctx = cv.getContext('2d');
var slider = root.querySelector('.mtb-dust-motes-range');
var valEl = root.querySelector('.mtb-dust-motes-val');
var timeEl = root.querySelector('.mtb-dust-motes-time');
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var W = 1, H = 1, motes = [], wind = 0.32, last = 0, acc = 0, left = 1440;

function seed() {
  var n = Math.round(Math.max(45, Math.min(150, W * H / 1750)));
  motes = [];
  for (var i = 0; i < n; i++) {
    var d = Math.random();
    motes.push({ x: Math.random() * W, y: Math.random() * H, d: d, r: 0.5 + d * 2.2,
                 s: 0.18 + d * 0.9, p: Math.random() * 6.283, w: 0.5 + Math.random() });
  }
}
function draw(dt) {
  ctx.clearRect(0, 0, W, H);
  for (var i = 0; i < motes.length; i++) {
    var m = motes[i];
    if (dt) {
      m.p += dt * 0.7 * m.w;
      m.x += ((0.1 + wind * 1.4) * m.s + Math.sin(m.p) * 0.22) * dt * 60;
      m.y -= (0.06 + m.s * 0.24) * dt * 60;
      if (m.x > W + 8) m.x = -8;
      if (m.x < -8) m.x = W + 8;
      if (m.y < -8) { m.y = H + 8; m.x = Math.random() * W; }
    }
    ctx.fillStyle = 'rgba(255,' + Math.round(226 - m.d * 26) + ',' + Math.round(188 - m.d * 48) + ',' + (0.1 + m.d * 0.52).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r, 0, 6.2832);
    ctx.fill();
  }
}
function fit() {
  var r = cv.getBoundingClientRect();
  W = Math.max(1, r.width); H = Math.max(1, r.height);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  seed();
  if (reduce) draw(0);
}
fit();
if (window.ResizeObserver) new ResizeObserver(fit).observe(cv);
slider.addEventListener('input', function () {
  wind = slider.value / 100;
  valEl.textContent = slider.value + '%';
});
function pad(n) { return (n < 10 ? '0' : '') + n; }
function frame(now) {
  if (!root.isConnected) return;
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
  last = now;
  draw(dt);
  acc += dt;
  if (acc >= 1) {
    acc -= 1;
    if (left > 0) left--;
    timeEl.textContent = pad(Math.floor(left / 60)) + ':' + pad(left % 60) + ' left';
  }
  requestAnimationFrame(frame);
}
if (!reduce) requestAnimationFrame(frame);

