var cv = root.querySelector('.mtb-flux-lattice-canvas');
var ctx = cv.getContext('2d');
var ping = root.querySelector('.mtb-flux-lattice-ping');
var valEl = root.querySelector('.mtb-flux-lattice-val');
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var W = 1, H = 1, px = 0, py = 0, t = 0, last = 0, ripples = [];

function fit() {
  var r = cv.getBoundingClientRect();
  W = Math.max(1, r.width); H = Math.max(1, r.height);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  px = W * 0.72; py = H * 0.42;
  if (reduce) draw();
}
function draw() {
  ctx.clearRect(0, 0, W, H);
  var halo = ctx.createRadialGradient(px, py, 0, px, py, Math.max(60, Math.min(W, H) * 0.9));
  halo.addColorStop(0, 'rgba(64,190,255,.14)');
  halo.addColorStop(1, 'rgba(64,190,255,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, W, H);
  var step = 15, x, y, i;
  for (y = step * 0.5; y < H; y += step) {
    for (x = step * 0.5; x < W; x += step) {
      var dx = x - px, dy = y - py;
      var d = Math.sqrt(dx * dx + dy * dy);
      var o = Math.sin(d * 0.05 - t * 2.2) * 4.4 * Math.exp(-d / 270);
      var e = 0;
      for (i = 0; i < ripples.length; i++) {
        var rp = ripples[i];
        var rx = x - rp.x, ry = y - rp.y;
        var rd = Math.sqrt(rx * rx + ry * ry) - rp.t * 240;
        e += Math.exp(-(rd * rd) / 700) * 7 * Math.max(0, 1 - rp.t / 1.5);
      }
      var k = Math.abs(o) + e;
      var a = 0.17 + Math.min(0.72, k * 0.11);
      var s = 1.5 + Math.min(2.6, k * 0.24);
      ctx.fillStyle = 'rgba(' + Math.round(96 + k * 14) + ',' + Math.round(180 + k * 8) + ',255,' + a.toFixed(3) + ')';
      ctx.fillRect(x + o - s / 2, y + o * 0.55 - s / 2, s, s);
    }
