var cv = root.querySelector('.mtb-tide-lines-canvas');
var ctx = cv.getContext('2d');
var modes = root.querySelectorAll('.mtb-tide-lines-mode');
var numEl = root.querySelector('.mtb-tide-lines-num');
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var W = 1, H = 1, t = 0, last = 0, acc = 0, filled = false;
var LINES = 14;

function yAt(i, x) {
  var base = H * (0.3 + i * (0.76 / LINES));
  var a1 = 5 + i * 0.85;
  var a2 = 3 + i * 0.4;
  return base + Math.sin(x * 0.019 + t * 0.9 + i * 0.55) * a1
              + Math.sin(x * 0.0071 - t * 0.55 + i * 0.9) * a2;
}
function fit() {
  var r = cv.getBoundingClientRect();
  W = Math.max(1, r.width); H = Math.max(1, r.height);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  if (reduce) draw();
}
function draw() {
  ctx.clearRect(0, 0, W, H);
  var step = 6, i, x;
  /* top line first: every filled band paints down to the baseline, so the next
     line down must cover it, leaving one visible stratum per contour */
  for (i = 0; i < LINES; i++) {
    var k = i / (LINES - 1);
    ctx.beginPath();
    ctx.moveTo(-4, yAt(i, -4));
    for (x = 0; x <= W + 4; x += step) ctx.lineTo(x, yAt(i, x));
    if (filled) {
      ctx.lineTo(W + 4, H + 6);
      ctx.lineTo(-4, H + 6);
      ctx.closePath();
      ctx.fillStyle = 'rgba(' + Math.round(10 + k * 24) + ',' + Math.round(52 + k * 60) + ',' + Math.round(96 + k * 70) + ',0.75)';
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(' + Math.round(120 + k * 60) + ',' + Math.round(210 + k * 30) + ',255,' + (0.16 + k * 0.5).toFixed(3) + ')';
    ctx.lineWidth = filled ? 1 : 0.9 + k * 0.7;
    ctx.stroke();
  }
}
fit();
if (window.ResizeObserver) new ResizeObserver(fit).observe(cv);
Array.prototype.forEach.call(modes, function (btn) {
  btn.addEventListener('click', function () {
    Array.prototype.forEach.call(modes, function (o) {
      o.setAttribute('aria-pressed', o === btn ? 'true' : 'false');
    });
    filled = btn.getAttribute('data-mode') === 'filled';
    root.setAttribute('data-mode', btn.getAttribute('data-mode'));
    draw();
  });
});
function frame(now) {
  if (!root.isConnected) return;
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
  last = now; t += dt; acc += dt;
  draw();
  if (acc > 0.4) {
    acc = 0;
    numEl.textContent = (1.8 + Math.sin(t * 0.35) * 0.6).toFixed(1);
  }
  requestAnimationFrame(frame);
}
if (!reduce) requestAnimationFrame(frame);

